import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA source implementing a simple LayerNorm (no backward)
# ----------------------------------------------------------------------
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

// -------------------- 1st kernel: compute per‑batch sum and sum‑squares ----------
extern "C"
__global__ void layernorm_sum_kernel(const __half* __restrict__ input,
                                     float* __restrict__ sum,
                                     float* __restrict__ sumsq,
                                     const int64_t batch,
                                     const int64_t N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int64_t i = idx; i < batch * N; i += stride) {
        const int64_t b = i / N;
        __half h = input[i];
        float f = __half2float(h);
        atomicAdd(&sum[b], f);
        atomicAdd(&sumsq[b], f * f);
    }
}

// -------------------- 2nd kernel: normalize, scale and shift -------------------
extern "C"
__global__ void layernorm_forward_kernel(const __half* __restrict__ input,
                                         __half* __restrict__ output,
                                         const __half* __restrict__ weight,
                                         const __half* __restrict__ bias,
                                         const float* __restrict__ mean,
                                         const float* __restrict__ var,
                                         const int64_t batch,
                                         const int64_t N,
                                         const float eps) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int64_t i = idx; i < batch * N; i += stride) {
        const int64_t b = i / N;
        const int64_t off = i % N;

        float m = mean[b];
        float v = var[b];
        float inv_std = rsqrtf(v + eps);

        float x = __half2float(input[i]);
        float w = __half2float(weight[off]);
        float b_val = __half2float(bias[off]);

        float y = (x - m) * inv_std;          // normalize
        y = y * w + b_val;                    // scale & shift
        output[i] = __float2half(y);
    }
}
'''

# Compile the inline extension (the harness will add the appropriate flags)
_ext = load_inline(name='layernorm_cuda',
                   cpp_sources='',
                   cuda_sources=cuda_src,
                   functions=['layernorm_sum_kernel', 'layernorm_forward_kernel'],
                   verbose=False)

# ----------------------------------------------------------------------
# Autograd Function (forward only – gradients are not supported)
# ----------------------------------------------------------------------
class _LayerNormCudaFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, weight, bias, eps):
        # input: (B, *norm_shape)  fp16
        B = input.shape[0]
        N = input.numel() // B  # size of normalized region per batch element

        device = input.device
        output = torch.empty_like(input)

        # temporary buffers for mean/var computation
        sum_buf = torch.zeros(B, dtype=torch.float32, device=device)
        sumsq_buf = torch.zeros(B, dtype=torch.float32, device=device)

        threads = 256
        blocks = min(1024, (B * N + threads - 1) // threads)

        # 1️⃣ sum & sum‑squares
        _ext.layernorm_sum_kernel(
            input,
            sum_buf,
            sumsq_buf,
            B,
            N,
            grid=(blocks, 1, 1),
            block=(threads, 1, 1)
        )

        # 2️⃣ mean & variance
        mean = sum_buf / N
        var = sumsq_buf / N - mean * mean

        # 3️⃣ normalize + scale + shift
        _ext.layernorm_forward_kernel(
            input,
            output,
            weight,
            bias,
            mean,
            var,
            B,
            N,
            eps,
            grid=(blocks, 1, 1),
            block=(threads, 1, 1)
        )

        # No backward support – mark tensors as non‑differentiable
        ctx.mark_non_differentiable(output)
        return output

    @staticmethod
    def backward(ctx, *grad_outputs):
        raise RuntimeError(
            "LayerNormCudaFunction does not support backward. "
            "Use the reference nn.LayerNorm for training."
        )

# ----------------------------------------------------------------------
# Drop‑in replacement for nn.LayerNorm
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    LayerNorm implemented with a custom CUDA kernel (FP16).
    Mirrors torch.nn.LayerNorm (affine=True, eps=1e-5 by default).
    """
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5):
        super().__init__()
        if not isinstance(normalized_shape, (list, tuple)):
            normalized_shape = (int(normalized_shape),)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = eps

        # learnable parameters – same shape as normalized dimensions
        self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float16))
        self.bias   = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float16))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure dtype / device are correct
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        return _LayerNormCudaFunction.apply(x, self.weight, self.bias, self.eps)

# ----------------------------------------------------------------------
# Helper to generate the same input as the reference implementation
# ----------------------------------------------------------------------
def get_inputs():
    batch_size = 16
    features = 64
    dim1 = 256
    dim2 = 256
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    # Returns the shape tuple that will be passed to ModelNew
    return [(64, 256, 256)]

# ----------------------------------------------------------------------
# Simple sanity‑check (optional)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    torch.manual_seed(0)
    model_ref = nn.LayerNorm((64, 256, 256), eps=1e-5).cuda().half()
    model_new = ModelNew((64, 256, 256)).cuda().half()

    # copy weights for a fair comparison
    with torch.no_grad():
        model_new.weight.copy_(model_ref.weight)
        model_new.bias.copy_(model_ref.bias)

    x = torch.rand(16, 64, 256, 256, dtype=torch.float16, device='cuda')
    out_ref = model_ref(x)
    out_new = model_new(x)

    print("max abs diff:", (out_ref - out_new).abs().max().item())
